jsonSchema:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "Code Review Widget Values",
  "type": "object",
  "properties": {
    "review": {
      "type": "object",
      "description": "The code review content to display.",
      "properties": {
        "good": {
          "type": "array",
          "description": "A list of positive aspects found in the code review.",
          "items": {
            "type": "string",
            "description": "A positive point."
          },
          "minItems": 0,
          "examples": [["Well-structured functions", "Clear variable names"]]
        },
        "issues": {
          "type": "array",
          "description": "A list of issues or problems found in the code review.",
          "items": {
            "type": "string",
            "description": "An issue or problem."
          },
          "minItems": 0,
          "examples": [["Missing error handling", "Inefficient loop"]]
        },
        "verdict": {
          "type": "string",
          "description": "The overall verdict or summary of the code review.",
          "examples": ["Approved with minor changes", "Needs significant refactoring"]
        }
      },
      "required": ["good", "issues", "verdict"]
    }
  },
  "required": ["review"]
}
